<?php
require_once __DIR__ . '/../includes/auth.php';$token=$_GET['token']??$_POST['token']??'';$hash=hash('sha256',$token);$s=db()->prepare('SELECT pr.*,r.email FROM review_password_resets pr JOIN reviewers r ON r.id=pr.reviewer_id WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>NOW() ORDER BY pr.id DESC LIMIT 1');$s->bind_param('s',$hash);$s->execute();$reset=$s->get_result()->fetch_assoc();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$reset){verify_csrf();$p=$_POST['password']??'';$c=$_POST['confirm_password']??'';if(strlen($p)<8)$error='Password must be at least 8 characters.';elseif($p!==$c)$error='Passwords do not match.';else{$ph=password_hash($p,PASSWORD_DEFAULT);$rid=(int)$reset['reviewer_id'];$rid2=(int)$reset['id'];$u=db()->prepare('UPDATE reviewers SET password=?,must_change_password=0,updated_at=NOW() WHERE id=?');$u->bind_param('si',$ph,$rid);$u->execute();$x=db()->prepare('UPDATE review_password_resets SET used_at=NOW() WHERE id=?');$x->bind_param('i',$rid2);$x->execute();set_flash('success','Password reset successfully. Please login.');redirect('reviewer/login.php');}}
$pageTitle='Reset Password';require __DIR__ . '/../includes/header.php';?>
<div class="card login-card"><div class="card-body p-4"><h4>Reset Password</h4><?php if(!$reset):?><div class="alert alert-danger">This reset link is invalid or expired.</div><?php else:?><?php if($error):?><div class="alert alert-danger"><?= e($error) ?></div><?php endif;?><form method="post"><?= csrf_field() ?><input type="hidden" name="token" value="<?= e($token) ?>"><div class="mb-3"><label class="form-label">New Password</label><input type="password" name="password" class="form-control" required></div><div class="mb-3"><label class="form-label">Confirm Password</label><input type="password" name="confirm_password" class="form-control" required></div><button class="btn btn-brand">Reset Password</button></form><?php endif;?></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>
